-- ============================================================================
-- HotD S3 Finale seed -- House of the Dragon, Season 3 Episode 8 (2026-08-09)
--
-- Repoints the existing Oscars content graph at the HotD finale:
--   categories     -> scoring events
--   nominees       -> characters (film_name column carries the House)
--   draft_entities -> characters (person) + dragons (film)
--   bingo_squares  -> 50 broadcast moments, all host-approved
--
-- DESTRUCTIVE: wipes existing Oscars content and all game rows that reference
-- it. Take a backup first:  supabase db dump --db-url <url> -f oscars-archive.sql
-- ============================================================================

BEGIN;

-- ── Clear dependent game data (FK order matters) ────────────────────────────
DELETE FROM bingo_marks;
DELETE FROM bingo_cards;
DELETE FROM confidence_picks;
DELETE FROM draft_picks;
DELETE FROM room_winners;
DELETE FROM category_nominees;
UPDATE categories SET winner_id = NULL, announced_at = NULL;
DELETE FROM messages;
-- Old rooms point at Oscars categories via rooms.active_spotlight_category_id,
-- which blocks the category delete below. The March rooms are meaningless now
-- and stale room codes would be a live hazard tonight, so clear them out.
-- Everything here is preserved in archive/oscars-2026-03/.
-- rooms.host_id -> players and players.room_id -> rooms form a cycle, so
-- break it first. host_id is nullable by design (a room is created with
-- host_id NULL and updated once the first player exists).
UPDATE rooms SET host_id = NULL, active_spotlight_category_id = NULL;
DELETE FROM players;
DELETE FROM rooms;
DELETE FROM categories;
DELETE FROM nominees;
DELETE FROM draft_entities;
DELETE FROM bingo_squares;

-- ── Scoring events ──────────────────────────────────────────────────────────

-- ── Characters ──────────────────────────────────────────────────────────────

-- ── Which characters are in play for which event ────────────────────────────

-- ── Draftable: characters ───────────────────────────────────────────────────

-- ── Dragons, as assignable event targets ───────────────────

-- ── Draftable: dragons ───────────────────────────

-- ── Bingo squares (all host-approved; is_objective = false) ─────────────────

COMMIT;

